// Do not edit by hand: re-generate when the sheet changes, so test titles keep matching the sheet.
export interface CmsCase {
  /** Test case ID, e.g. CMS-TC-003. */
  id: string;
  /** Column A, e.g. User Management. */
  menu: string;
  /** Column B, e.g. Users. */
  submenu: string;
  /** Column C, e.g. Search. */
  feature: string;
  steps: string;
  expected: string;
}

